export function canAdvanceBroadcast(record, parent) {
  if (record.status === "drafted") {
    return false;
  }
  if (record.status === "cleared") {
    return record.reading > 0 && parent !== null;
  }
  if (record.status === "aired") {
    return record.reading >= 1 && record.reading <= 500;
  }
  return false;
}

